import{_ as o,o as e,c as r,a2 as n}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"搭建节点","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodes.md","filePath":"guide/nodes.md","lastUpdated":1793837004000}'),a={name:"guide/nodes.md"};function s(l,t,d,i,g,h){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="搭建节点" tabindex="-1">搭建节点 <a class="header-anchor" href="#搭建节点" aria-label="Permalink to &quot;搭建节点&quot;">​</a></h1><p>在落地机上部署代理节点（入站）。所有配置由面板生成，节点上的 agent 只负责下载内核、写入配置、运行和守护进程。</p><blockquote><p>术语对照：面板菜单里的 <strong>落地</strong> 页就是本文档所说的节点 / 入站管理；菜单 <strong>规则</strong> 在文档里称转发（见 <a href="./forward">流量转发与管理</a>），菜单 <strong>共享</strong> 即联邦 / 面板共享（见 <a href="./relay">对接中转</a>）。</p></blockquote><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ul><li>落地机已按 <a href="./install">安装部署</a> 装好节点 agent，并在面板里显示在线</li><li>Linux amd64 / arm64，root 权限</li><li>建议安装 nftables（<code>apt install nftables</code>）：入站流量统计、白名单和 Hysteria2 端口跳跃依赖它。一般功能没有 nftables 也能跑，但有一个例外要先知道：入站开启了<strong>白名单</strong>、或节点上有<strong>独立 Snell 内核</strong>的服务端时，内核启动前必须先把 nft 规则同步成功；nftables 缺失或同步失败时，受保护的内核会<strong>整体不启动</strong>（该内核下全部入站下线）——这是刻意的 fail-closed 口径，不是「少几个功能」的降级运行。这类节点务必先装好 nftables 再启用白名单 / Snell。这里的 Snell 只指独立 Snell 内核：sing-box 内置的 Snell 入站走配置面拦截、不经 agent 的 nft 同步，不在这条前置要求之列</li></ul><h2 id="安装内核" tabindex="-1">安装内核 <a class="header-anchor" href="#安装内核" aria-label="Permalink to &quot;安装内核&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>内核</strong> 标签 → <strong>安装内核</strong> → 选择节点和内核。</p><table tabindex="0"><thead><tr><th>内核</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Xray</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用官方校验文件校验</td></tr><tr><td>sing-box</td><td>默认最新版，可指定</td><td>从 GitHub Release 下载，用 Release 资产的 SHA256 校验</td></tr><tr><td>Snell</td><td>5.0.1 / 6.0.0 / 4.1.1</td><td>只从官方 <code>dl.nssurge.com</code> 下载，使用内置的校验值；6.0.0 为 beta、仅 v6 入站可用</td></tr></tbody></table><p>一台节点可以同时安装多个内核，内核按节点分组显示。点击内核可以启停、重启、查看日志、更换版本或卸载；节点重启后内核会自动恢复运行。</p><h2 id="新建入站" tabindex="-1">新建入站 <a class="header-anchor" href="#新建入站" aria-label="Permalink to &quot;新建入站&quot;">​</a></h2><p><strong>落地</strong> 页 → <strong>入站</strong> 标签 → <strong>新建入站</strong> → 选择节点和内核 → 点击一个快速模板 → 填名称 → <strong>创建并下发</strong>。</p><p>端口留空会随机分配，UUID、密码、密钥留空会自动生成。</p><table tabindex="0"><thead><tr><th>模板</th><th>内核</th><th>说明</th></tr></thead><tbody><tr><td>VLESS + Reality + Vision</td><td>Xray / sing-box</td><td>推荐，无需域名和证书</td></tr><tr><td>VLESS + XHTTP + Reality</td><td>Xray</td><td></td></tr><tr><td>Shadowsocks 2022</td><td>Xray / sing-box</td><td></td></tr><tr><td>Trojan + TLS（自签）</td><td>Xray / sing-box</td><td>需要填写域名</td></tr><tr><td>VMess + WS + TLS</td><td>Xray / sing-box</td><td>兼容老客户端</td></tr><tr><td>Hysteria2</td><td>sing-box</td><td>基于 QUIC，可选端口跳跃</td></tr><tr><td>TUIC v5</td><td>sing-box</td><td>基于 QUIC</td></tr><tr><td>AnyTLS</td><td>sing-box</td><td></td></tr><tr><td>SS2022 + ShadowTLS</td><td>sing-box</td><td>仅 TCP</td></tr><tr><td>NaïveProxy</td><td>sing-box</td><td>需要域名和真实证书</td></tr><tr><td>Snell / Snell + ShadowTLS</td><td>Snell / sing-box（≥1.14）</td><td>Surge 专用</td></tr></tbody></table><h3 id="证书" tabindex="-1">证书 <a class="header-anchor" href="#证书" aria-label="Permalink to &quot;证书&quot;">​</a></h3><p>TLS 类入站有三种证书来源：</p><ul><li><strong>自动生成自签证书</strong>：开箱即用，客户端需要允许不安全证书（分享链接已自动带上）</li><li><strong>使用节点上的证书文件</strong>：填写证书和私钥在节点上的绝对路径</li><li><strong>自动申请证书（ACME）</strong>：仅 sing-box，需要 sing-box 1.14 及以上 <ul><li>域名必须解析到该节点</li><li>HTTP 验证：节点 80 端口要能从公网访问</li><li>DNS 验证：支持 Cloudflare（API Token）和阿里云（AccessKey），不需要 80 端口。面板侧在入站表单的证书区选 <strong>自动申请证书（ACME）</strong> 后，把 <strong>验证方式</strong> 选为 <strong>Cloudflare DNS</strong> 或 <strong>阿里云 DNS</strong>，再按下文填凭据</li><li>证书由 sing-box 自动续期</li></ul></li></ul><p>DNS 验证的凭据获取与填写（两家二选一）：</p><ul><li><strong>Cloudflare</strong>：登录 Cloudflare 控制台 → 右上角头像 → <strong>My Profile（我的个人资料）</strong> → <strong>API Tokens</strong> → <strong>Create Token</strong> → 选 <strong>Edit zone DNS</strong> 模板（或自建令牌：权限给 <strong>Zone → DNS → Edit</strong>，Zone Resources 只勾选要签证书的那个域名 Zone，不要放行全部 Zone）；创建后复制 Token，填入面板的 <strong>API Token</strong> 字段（只有一个字段）。防错：只给 Zone 级 DNS 编辑权即可，<strong>不要填 Global API Key</strong>；Zone 选错或没包含目标域名会直接签发失败。自检：保存入站后看节点上 sing-box 的日志，出现证书签发成功即通；报 403 多半是 Token 权限或 Zone 范围不对，回控制台核对这两项。</li><li><strong>阿里云</strong>：登录阿里云控制台 → 右上角头像 → <strong>AccessKey 管理</strong> → <strong>创建 AccessKey</strong>，拿到 <strong>AccessKey ID</strong> 与 <strong>AccessKey Secret</strong>，分别填入面板的 <strong>AccessKey ID</strong> / <strong>AccessKey Secret</strong> 两个字段；该账号要有云解析 DNS 的读写权限（系统策略 <code>AliyunDNSFullAccess</code>，或等价的自定义策略）。防错：<strong>Secret 只在创建时显示一次</strong>，关掉页面就再也看不到，先保存好再填面板；AccessKey 等同账号钥匙，建议用 RAM 子账号只授 DNS 权限，不要长期用主账号 AccessKey。自检同上：看 sing-box 日志的签发结果，报权限类错误先回控制台查该账号的 DNS 授权。</li></ul><p>两家的凭据都只存面板、保存后不回显（编辑入站时字段显示「已保存，留空不修改」，留空即保留原值）。</p><p>NaïveProxy 必须使用真实证书（ACME 或证书文件）。</p><h3 id="hysteria2-端口跳跃" tabindex="-1">Hysteria2 端口跳跃 <a class="header-anchor" href="#hysteria2-端口跳跃" aria-label="Permalink to &quot;Hysteria2 端口跳跃&quot;">​</a></h3><p>在 Hysteria2 入站里填写一段 UDP 端口，例如 <code>20000-30000</code>。节点会用 nftables 把这段端口转到入站端口，客户端在其中随机切换，缓解运营商对单个 UDP 端口的限速。</p><ul><li>范围不能包含入站端口本身，不能和其他入站、转发或节点的转发端口段重叠</li><li>只有直连地址带跳跃参数；经中转连接时只转发一个端口，不跳跃</li></ul><h3 id="监听地址" tabindex="-1">监听地址 <a class="header-anchor" href="#监听地址" aria-label="Permalink to &quot;监听地址&quot;">​</a></h3><p>默认监听 <code>::</code>（同时支持 IPv4 和 IPv6）。如果节点在内核启动参数里完全禁用了 IPv6（<code>ipv6.disable=1</code>），部分内核会绑定失败，此时在高级选项里把监听地址改为 <code>0.0.0.0</code>。</p><h3 id="空闲超时-秒" tabindex="-1">空闲超时（秒） <a class="header-anchor" href="#空闲超时-秒" aria-label="Permalink to &quot;空闲超时（秒）&quot;">​</a></h3><p>入站创建/编辑表单里的<strong>空闲超时（秒）</strong>：该入站连接的空闲关断窗口。留空表示不设置，走 Xray 默认 300 秒；填 <code>1–86400</code> 的整数；填 <code>0</code> 表示清除已设的值（与留空等效，恢复默认 300 秒；面板不下发显式的 0，Xray 层面 0 没有独立语义）。</p><ul><li><p><strong>不限</strong>：勾选输入框旁的「不限」，该入站的连接永不因空闲自动断开。实现上存为 <code>-1</code>、渲染为 <code>31536000</code> 秒（365 天）：Xray 的关断窗口是 (N, 2N]，365 天对应实际 1–2 年才断，等同于永不断；更大的数没有意义——面板升级或节点重启本来就会断会话，且 2N 须远离 int32 上限。常驻连接（如自动客服系统）用此项；取消勾选恢复原值。</p></li><li><p><strong>关断语义（上游 Xray 机制，非面板缺陷）</strong>：Xray 的空闲计时器以设定秒数 N 为一格、按格检查——全程无数据的会话约 N 秒后断开；有过数据的会话，自末次数据起 <strong>N–2N 秒</strong>后断开（数据落在检查格内的位置决定具体值：刚过格线的数据约 2N 秒断，临近格线的数据约 N 秒断；实测 N=5 时带数据会话 10.2 秒断、静默会话 5.2 秒断，N=10 时带数据会话 20.2 秒断）。面板下发的 <code>policy.levels[].connIdle</code> 与 <code>flmx-idle-*</code> 出站的 <code>userLevel</code> 均与设定值逐字一致、未翻倍——2N 是上游计时粒度，不是面板多算了一倍；把下发值减半会让静默会话提前到 N/2 断开，故面板不以改值“补偿”，只按实测语义写明承诺。</p></li><li><p>VMess/SS 的会话关断约 3.1 秒且不随设定值变化，静默约 1.1 秒——属上游 Xray-core 行为，关得比设定快，安全方向，与面板渲染无关。</p></li><li><p><strong>仅 Xray 内核可用</strong>。sing-box 内核没有 Xray 式空闲超时（TCP 靠 keepalive 保活、UDP 会话默认 5 分钟清理、仅 TUN 有 <code>udp_timeout</code>），sing-box 入站上该字段禁用并会明示原因。</p></li><li><p>不同入站可设不同值，互不干扰；删除入站后对应的超时配置一并撤下。</p></li></ul><h3 id="vless-加密-enc-与「iepl专用」预设" tabindex="-1">VLESS 加密（ENC）与「IEPL专用」预设 <a class="header-anchor" href="#vless-加密-enc-与「iepl专用」预设" aria-label="Permalink to &quot;VLESS 加密（ENC）与「IEPL专用」预设&quot;">​</a></h3><p>Xray 内核的 VLESS 入站可开启 VLESS 加密（ENC），启用 ENC 的入站在列表里带红色「IEPL专用」标识。流控只有一条判据：<strong>纯 ENC 配置（ENC 开 + 安全无）不开启流控</strong>——两条填充路径同此口径：</p><ul><li>点红色的「<strong>IEPL专用</strong>」标签：套用纯 ENC 预设——VLESS / TCP / 安全无、ENC 开、ML-KEM-768 后量子认证、xorpub 外观、无 SNI，并同时勾选上面的空闲超时「不限」。只填表单、不创建，也不改已填的节点、端口与名称。</li><li>直接拨动「启用 VLESS 加密（ENC）」开关：自动套用标准配置（TCP、安全无、ML-KEM-768 认证、native 外观），同样不开启流控。</li></ul><p>流控功能本身不受影响：VLESS Reality 等其他配置照常可以开启 XTLS Vision 流控。另外要分清：上面「纯 ENC 不开启流控」说的是两条<strong>填充路径的预设结果</strong>，不是后端禁令——手工编辑入站时把 ENC 与 Vision 流控组合使用是允许的（ENC 是 Vision 的合法加密层），保存与导入都不会被拒，只是没有任何预设会替你这样填。</p><h3 id="出站" tabindex="-1">出站 <a class="header-anchor" href="#出站" aria-label="Permalink to &quot;出站&quot;">​</a></h3><p>服务器侧的分流和链式：客户端照常连本节点，由节点内核决定流量从哪里出去。想在客户端订阅里组合“中转 → 落地”，见 <a href="./subscription#链式代理">订阅的链式代理</a>。</p><p>点入站 → <strong>出站</strong>，有两部分（对话框顶部还能设置出站 IP 策略，见 <a href="#出站-ip-策略">出站 IP 策略</a>）：</p><ul><li><strong>默认去向</strong>：直连（从本节点出去），或选另一个入站（其他节点上的入站、导入的节点），流量再经它出去，网站看到的是它的 IP（链式代理）</li><li><strong>分流规则</strong>：按目标把一部分流量送到别处，从上到下匹配，先命中先生效，都不命中的走默认去向</li></ul><p>每条分流规则选分类或填自定义域名 / IP，再选去向：<strong>直连</strong>、<strong>阻断</strong> 或某个出站节点。</p><table tabindex="0"><thead><tr><th>分类</th><th>内容</th></tr></thead><tbody><tr><td>流媒体</td><td>Netflix、Disney+、YouTube、HBO、Prime Video、Spotify、TikTok</td></tr><tr><td>AI</td><td>ChatGPT、Claude、Gemini</td></tr><tr><td>常用</td><td>Google、Telegram</td></tr><tr><td>其他</td><td>广告、BT 下载、回国流量（中国大陆的域名和 IP）</td></tr></tbody></table><p>常见用法：</p><ul><li>只让 Netflix / ChatGPT 走有解锁 IP 的节点（例如导入的机场节点），其他流量照常直连</li><li>落地机阻断 BT 和回国流量，避免被投诉或滥用</li><li>A → B → C 多级：给 A 的入站选 B 作为默认去向，再给 B 的入站选 C；每个节点只连下一跳</li><li>自定义域名包含子域名，例如填 <code>example.com</code> 也匹配 <code>www.example.com</code></li></ul><p>注意事项：</p><ul><li>分类数据自动更新：Xray 用 v2fly 的 geosite / geoip 数据，由节点 agent 经内置的 GitHub 下载路线自动测速直选下载（先测直连，直连不通才按延迟在内置代理候选中选最快，无需在面板里配置加速地址），节点每天检查一次，有新版本就下载、校验后替换并重启 Xray（启动失败会恢复原文件），内核日志里可以看到更新记录；sing-box 的分流规则集走同一条路线：由节点 agent 经内置的 GitHub 下载路线测速选线预下载（下载时校验规则集文件格式，假活/错误页会被判失败换线），落盘后以本地规则集形式交给 sing-box 加载，agent 还会周期性检查规则集更新（内容有变化才替换并重启）——因此 sing-box 分流<strong>不要求落地机直连访问 GitHub</strong>；规则集下载失败且本地没有可用副本时，本次配置下发会在写盘前中止、继续使用上一次能运行的配置（见下），已有副本时刷新失败会沿用旧副本并在内核日志中记录</li><li>Xray 能连接 VLESS / VMess / Trojan / Shadowsocks（不含插件和 ShadowTLS）/ SOCKS5 / HTTP 出站节点；Hysteria2、TUIC、AnyTLS 等请用 sing-box 内核；Snell 内核的入站不能再设出站或分流</li><li>出站节点是本面板的自签证书入站时，Xray 用证书指纹校验；导入的节点如果跳过了证书验证，Xray 无法连接（新版 Xray 已移除 <code>allowInsecure</code>），请改用 sing-box</li><li>开启了“获取真实客户端 IP”的入站只能经中转连接，不能作为出站节点；只监听本机的入站只能被同一节点上的入站选用</li><li>出站节点开启了白名单时，会自动放行经它出站的节点；规则之间形成循环（A 经 B、B 又经 A）时无法保存</li><li>被选作默认去向或分流去向的入站不能直接删除，需先解除；订阅源刷新时也会保留这些节点。出站节点如果随<strong>节点一起被删除、或其所在内核被强制卸载</strong>，原本经它出去的流量会被丢弃（不会改为直连），请重新选择；被引用的入站所在内核<strong>普通卸载会被拒绝</strong>，需先解除引用或确认强制卸载。</li><li>用户流量统计照常按用户计算</li><li>保存会重启节点内核，正在经这个节点连接的会断开一下重连。如果你正用这个节点打开面板，保存时连接会中断，面板会在节点恢复后自动确认是否已保存</li><li>新配置下发或启动失败时（例如分流规则集下载失败导致下发中止、或内核无法按新配置启动），节点会继续使用上一次能运行的配置并显示错误，不会因此掉线</li></ul><h2 id="分享与订阅" tabindex="-1">分享与订阅 <a class="header-anchor" href="#分享与订阅" aria-label="Permalink to &quot;分享与订阅&quot;">​</a></h2><ul><li>点击入站 → <strong>分享</strong>（电脑上也可以直接点行内的“分享”按钮）：显示通用分享链接和二维码；Snell 没有通用链接，显示 Surge 配置行。Surge 用户请使用 Surge 订阅</li><li><strong>订阅</strong> 页：一个链接包含落地和中转线路，可以建多个、分别过滤和改名，也可以分享给别人，见 <a href="./subscription">订阅</a></li><li><strong>分享地址</strong>：新建 / 编辑入站时可选客户端连接用的地址——<strong>自动</strong>（节点默认地址）、<strong>节点 IPv4</strong>、<strong>节点 IPv6</strong> 或 <strong>自定义域名 / IP</strong>。分享链接、订阅下发与链式代理的下一跳统一使用该地址；选 IPv4 / IPv6 后节点地址变化会自动跟随；节点没有对应地址族时不能选该档（保存会报错）。自定义地址须是规范主机名或 IP（尾点域名会自动规范化；含下划线、中文域名、回环地址的值不接受）</li></ul><table tabindex="0"><thead><tr><th>订阅格式</th><th>适用客户端</th><th>不包含</th></tr></thead><tbody><tr><td>自动识别</td><td>按客户端 UA 返回对应格式</td><td></td></tr><tr><td>Clash / Mihomo</td><td>Clash Verge、Stash、FlClash</td><td>NaïveProxy、Snell（自建入站）</td></tr><tr><td>sing-box</td><td>SFA / SFI / SFM</td><td>XHTTP</td></tr><tr><td>Shadowrocket</td><td>Shadowrocket</td><td>NaïveProxy</td></tr><tr><td>Loon</td><td>Loon</td><td>TUIC、gRPC、XHTTP、Snell、NaïveProxy、TCP+HTTP 头伪装</td></tr><tr><td>Quantumult X</td><td>Quantumult X</td><td>Hysteria2、TUIC、gRPC、XHTTP、ShadowTLS、Snell、NaïveProxy、TCP+HTTP 头伪装</td></tr><tr><td>通用 base64</td><td>v2rayN、NekoBox</td><td>Snell</td></tr><tr><td>Surge</td><td>Surge</td><td>VLESS、Reality、gRPC、XHTTP、NaïveProxy、TCP+HTTP 头伪装</td></tr></tbody></table><p>Snell 的下发按版本与客户端区分：Clash / Mihomo 不下发自建 Snell 入站（v4 / v5 / v6 均不下发，原因见下方版本提示）；Stash 与 Shadowrocket 下发 v4 / v5 入站（按 v4 客户端口径渲染），v6 入站不下发（客户端无 v6 支持）；sing-box 仅 1.14 及以上版本下发。注意：sing-box 是否下发 Snell 按<strong>拉取请求的 UA</strong> 判定（须 sing-box 1.14+ 的 UA），与是否用 <code>?format=</code> 指定格式无关；用浏览器或普通工具拉取（UA 不带 sing-box 版本）时不含 Snell，属正常现象，用 sing-box 1.14+ 客户端直接拉取（含 <code>?format=singbox</code> 链接）即可。另注意<strong>导入</strong>的 Snell 节点按格式另有口径（与上面自建入站的分流不同）：sing-box 订阅侧略过 v1–v3（只下发 v4 / v5（按 v4 渲染）/ v6 口径）；Clash 格式下发 v1 / v2 / v3，其中 v1 / v2 强制以 <code>udp: false</code> 输出（mihomo 不接受这两个版本的 UDP 开关为真），v4 / v5 不下发（mihomo 收到会整份拒绝，理由同自建面）；Stash / Shadowrocket 下发 v1–v4（原样）、v5 按 v4 渲染下发，v6 与负数等异常版本略过不下发。导入的 Snell + ShadowTLS 节点：sing-box 侧经 shadow-tls 转换（detour 双出站）下发，两种存储形态（<code>shadow-tls</code> 键形态、Clash YAML 的 <code>obfs-opts</code> 形态）同口径；带 shadow-tls / restls / jls 混淆的导入节点在 Clash 格式不下发（mihomo 无此混淆模式、收到会整份拒绝）；v3 带 http / tls 混淆的导入节点 Clash 照常下发、sing-box 侧不下发（sing-box 的 Snell 客户端没有混淆模式可表达）。</p><p>NaïveProxy 的 sing-box 出站需要 sing-box 1.13 及以上：节点 sing-box 低于 1.13 时，以 NaïveProxy 节点为链式落地（默认去向或分流目标）在保存、下发和更换内核版本时会被点名拒绝，把节点 sing-box 升到 1.13 及以上即可；订阅侧同理，sing-box 客户端低于 1.13（按拉取请求的 UA 判定）时不下发 NaïveProxy 节点、其余节点照常下发。自建 NaïveProxy 入站本身不受此下限影响。</p><blockquote><p>客户端版本提示：mihomo 官方版本（已实测 1.19.16 / 1.19.17，即 Clash Verge、Mihomo Party、FlClash 等现行发行所带内核线）只接受 Snell v3，含 Snell v4 条目的配置会被整份拒绝——这是现行版本的口径、不是旧版本缺陷，升级 mihomo 也不会改变。面板因此不在 Clash 格式下发自建 Snell 入站；Stash / Shadowrocket 与 sing-box（1.14 以上）侧照常下发。</p></blockquote><p>VLESS 加密（ENC）入站不在上表的协议排除之列，但只有 Clash / Mihomo、Stash 与通用 base64 输出会携带它的完整 <code>encryption</code> 参数，其余格式（sing-box、Shadowrocket、Loon、Quantumult X、Surge）直接略过这类入站。</p><h2 id="批量操作" tabindex="-1">批量操作 <a class="header-anchor" href="#批量操作" aria-label="Permalink to &quot;批量操作&quot;">​</a></h2><p>入站多了不好管理时，点列表上方的 <strong>多选</strong>：点卡片勾选，<strong>全选</strong> 会选中当前列表里显示的全部入站（可以先用搜索或节点筛选缩小范围），然后可以批量 <strong>启用</strong>、<strong>停用</strong> 或 <strong>删除</strong>。每个受影响的内核只下发一次配置。</p><h2 id="节点延迟" tabindex="-1">节点延迟 <a class="header-anchor" href="#节点延迟" aria-label="Permalink to &quot;节点延迟&quot;">​</a></h2><p>面板可以让每个节点定时向一组测试点做 TCP 延迟探测，在节点卡片和列表里直接看到各线路的延迟。</p><h3 id="配置测试点" tabindex="-1">配置测试点 <a class="header-anchor" href="#配置测试点" aria-label="Permalink to &quot;配置测试点&quot;">​</a></h3><p><strong>网站配置 → 延迟测试点</strong>：添加测试点（名称、地址、端口），最多 30 个；可以把最多 3 个固定显示在节点卡片上（其余的点进下拉查看）。仅管理员可配置。</p><p>测试点改名后，已选择该测试点的节点会自动跟随新名称；删除测试点后，相关节点回退到全局默认。</p><h3 id="查看延迟" tabindex="-1">查看延迟 <a class="header-anchor" href="#查看延迟" aria-label="Permalink to &quot;查看延迟&quot;">​</a></h3><p><strong>节点</strong> 页卡片视图和列表视图都有延迟显示：每个测试点一个数值，颜色按延迟分档：</p><table tabindex="0"><thead><tr><th>延迟</th><th>颜色</th></tr></thead><tbody><tr><td>&lt; 100ms</td><td>绿</td></tr><tr><td>100–300ms，或有丢包</td><td>橙</td></tr><tr><td>≥ 300ms，或丢包 ≥ 50%，或不可达</td><td>红</td></tr></tbody></table><h3 id="节点自选测试点" tabindex="-1">节点自选测试点 <a class="header-anchor" href="#节点自选测试点" aria-label="Permalink to &quot;节点自选测试点&quot;">​</a></h3><p>默认所有节点测全局启用的测试点。想让某个节点只测指定的点：节点操作菜单 → <strong>测试点</strong> → 切到自选并勾选，保存后会立即重测该节点。注意两种「空选」的区别：未启用自选时跟随全局默认；启用自选但不勾任何点，表示该节点<strong>不做</strong>延迟探测。</p><h2 id="本月流量-网卡" tabindex="-1">本月流量（网卡） <a class="header-anchor" href="#本月流量-网卡" aria-label="Permalink to &quot;本月流量（网卡）&quot;">​</a></h2><p><strong>节点</strong> 页卡片 / 列表与实时统计区显示每个节点的 <strong>本月流量（网卡）</strong>（上行 / 下行分列）：</p><ul><li>口径是<strong>整台机器网卡的流量</strong>（agent 上报网卡累计计数的差分），包含该机的一切流量，不只是经面板转发的业务；</li><li>按查看者浏览器时区的自然月统计（每月 1 日起算），逐小时落账；</li><li>这是机器用量的参考数字，与 <a href="./subscription#流量统计">订阅流量统计</a>（按订阅凭据计）和转发计费（按隧道倍率折算）的口径都不同，<strong>不能互相换算、不能作计费依据</strong>；</li><li>网卡增删不会重复计入；agent 或整机重启后的第一个统计窗口可能少计一小段，属已知口径。</li></ul><h2 id="节点调优" tabindex="-1">节点调优 <a class="header-anchor" href="#节点调优" aria-label="Permalink to &quot;节点调优&quot;">​</a></h2><p>优化节点内核的网络参数（sysctl），适合跨境、高延迟线路。</p><p>操作路径：<strong>节点</strong> 页 → 某节点的操作菜单 → <strong>调优</strong>（仅 agent 模式节点显示，nftables 模式节点没有此入口）。</p><h3 id="自动调优" tabindex="-1">自动调优 <a class="header-anchor" href="#自动调优" aria-label="Permalink to &quot;自动调优&quot;">​</a></h3><p>点 <strong>自动调优</strong> 后 Agent 在后台执行：自动选择公共 iperf3 对端（Leaseweb / Clouvider / OVH），实测四并发吞吐，读取服务器内存后按实测带宽计算并应用参数，最后验证单连接和多连接吞吐。任务在 Agent 后台执行，关闭窗口不会中断，再次打开可继续查看阶段、进度与日志；点 <strong>停止任务</strong> 会停止测速，已应用的基础参数保留，可随时恢复原配置。</p><ul><li>无需填写带宽和延迟；缓冲区按实测带宽 × 150 ms 路径估值计算（150 ms 是路径估值，不是到测速对端的延迟；对端只用于测量带宽，不能代表实际用户线路）</li><li>首次使用会自动安装缺少的测速依赖（iperf3、iproute2 等）；测速会向公共对端发送流量，<strong>千兆线路基础测速约消耗 4–7 GB</strong>（含对端短测排序）；公共对端忙或不可达时会报错，不会用假定的千兆带宽代替实测</li><li>自动调优与深度优化要求节点 Agent 为调优移植版；旧 Agent 只显示升级提示，不会悄悄沿用固定带宽；手动调优（按带宽/延迟应用）仍可走后端接口，但弹窗已不再提供手填入口</li><li>选点说明：Agent 先以两次 TCP 握手取最小延迟排序，再对前 4 个候选各做 5 秒单流短测、取实测最快的对端跑全量测速——握手延迟只是带宽的代理变量，冷启动时可能虚高数十倍，短测排序以实测为准</li></ul><table tabindex="0"><thead><tr><th>调优组</th><th>说明</th></tr></thead><tbody><tr><td>BBR 拥塞控制</td><td>高延迟、有丢包的线路提速明显（需要内核 4.9+）</td></tr><tr><td>加大缓冲区</td><td>跨境长距离线路单连接跑得更快</td></tr><tr><td>TCP 连接优化</td><td>开启 Fast Open、空闲后不降速、自动探测 MTU</td></tr><tr><td>高并发队列</td><td>连接多时不丢新连接</td></tr><tr><td>IPv4 转发</td><td>内核转发（nftables 端口转发）需要</td></tr><tr><td>文件句柄上限</td><td>系统允许打开更多连接和文件</td></tr></tbody></table><ul><li><strong>应用</strong>：参数写入 <code>/etc/sysctl.d/99-flmx-tuning.conf</code>，重启后依然生效；应用前各参数的原值会备份，<strong>恢复原配置</strong> 时写回原值并删除该配置文件</li><li>不支持的内核参数只会 warning 跳过，不会中断整个应用过程</li><li>节点 agent 版本过旧时会提示升级节点后再试</li></ul><h3 id="深度优化" tabindex="-1">深度优化 <a class="header-anchor" href="#深度优化" aria-label="Permalink to &quot;深度优化&quot;">​</a></h3><p>自动调优完成后可进一步点 <strong>深度优化</strong>，扫描线路限速器的拐点并应用出向整形（HTB 全局上限 + fq pacing），适合被限速器丢包拖慢的线路。</p><ul><li><strong>前置</strong>：需要 24 小时内的自动调优测速结果；没有或结果过期时，窗口会说明原因，点 <strong>自动调优并继续</strong>，完成后会自动显示预计流量和本次流量预算</li><li><strong>流量成本</strong>：开始前显示预计流量与本次预算，勾选「允许本次测速使用上述流量」后才执行。千兆线路一轮深度扫描约消耗 29 GB（2.5G 约 69 GB、10G 两三百 GB）；本次预算 = min(1000, 预计 × 1.25) GB，最多 1000 GB，预计流量本身超过上限时不会启动。预算只计测速增量（扫描前先测 5 秒本底业务流量并扣除），达到预算即停并恢复扫描前队列；单个任务最长 25 分钟</li><li><strong>扫描与验证</strong>：先不限速探测，再逐档加整形试探拐点（丢包率跳变判定），只有取得可靠拐点才应用整形并验证吞吐；验证失败、无拐点、对端过慢或结果不确定时保留原队列与原整形配置</li><li><strong>手动应用整形</strong>：弹窗内另有手填入口——在「手动应用整形」处填入整形速率（Mbps）后直接应用并验证，跳过拐点扫描（填入值不经测速验真，请按线路实际限速填写）；它与扫描路径共用同一套前置与约束：仍需 24 小时内的自动调优结果、本次流量预算与勾选同意，应用失败同样恢复原队列</li><li><strong>恢复与持久化</strong>：扫描前保存出口队列原样与整形配置；扫描中途任何失败/中断/取消都恢复原队列。整形提交后由 <code>flmx-tuning-qdisc.service</code> 在宿主机启动时恢复；容器没有 systemd，已提交的整形随 Agent 启动重新下发。Agent 意外退出后，下次启动会尝试恢复中断扫描前的队列</li><li><strong>限制</strong>：节点已有外部整形器或自定义流量分类时扫描会停止（不覆盖现有配置）；整形需要 root + <code>tc</code>（iproute2）+ 出口网卡可写 qdisc，受限容器或缺 <code>tc</code> 的精简镜像会报错并保留原配置</li><li><strong>恢复原配置</strong>：撤销 FLMX 的调优<strong>与</strong>整形（含删除整形脚本与 systemd unit、恢复原队列、删除测速结果）；恢复前若找不到队列备份且存在整形配置，会拒绝恢复以保配置不丢</li></ul><h3 id="手填入口已删的后果" tabindex="-1">手填入口已删的后果 <a class="header-anchor" href="#手填入口已删的后果" aria-label="Permalink to &quot;手填入口已删的后果&quot;">​</a></h3><p>调优弹窗不再提供手填带宽/延迟与分组勾选，1.4.8 的一键测算也随之失去入口（后端探测接口仍在，只是弹窗不再调用）。自动任务失败或对端不可达时，带宽/延迟没有手动兜底；需要手动调优时请走后端接口或等自动任务恢复。注意区分：<strong>深度优化</strong>的「手动应用整形」手填入口不在此列、仍然可用，见上节。</p><h2 id="回程路由追踪" tabindex="-1">回程路由追踪 <a class="header-anchor" href="#回程路由追踪" aria-label="Permalink to &quot;回程路由追踪&quot;">​</a></h2><p>查看节点到各测试点的回程经过了哪条骨干网，辅助判断线路质量。</p><p>操作路径：<strong>节点</strong> 页 → 点击延迟单元格，在下拉菜单里选 <strong>回程路由</strong> → 弹出路由详情，显示每一跳的 IP、延迟和所属线路。</p><p>自动识别的线路：</p><table tabindex="0"><thead><tr><th>线路</th><th>说明</th></tr></thead><tbody><tr><td>电信 CN2 GIA / CN2 GT</td><td>高端/普通 CN2</td></tr><tr><td>电信 163</td><td>普通电信</td></tr><tr><td>联通 4837 / 9929</td><td>普通/高端联通</td></tr><tr><td>移动 CMI / CMIN2</td><td>普通/高端移动</td></tr></tbody></table><p>路由结果每 24 小时自动刷新一次，失败时 6 小时后重试。需要节点有 raw socket 权限（root 或 <code>CAP_NET_RAW</code>），无权限时会优雅报错。</p><p>双栈节点会把每个测试点的 IPv4、IPv6 回程各测一条：路由详情里每个测试点分两行显示，节点卡片上 IPv6 线路与 IPv4 不同时多一个「v6」小标签，IPv6 线路变化也会在回程变化通知里单独一行提醒。双栈回程需要把节点 agent 升级到 1.2.0 或更高版本随附的版本；未升级的节点照常显示 IPv4 回程，不报错、不误报，升级后自动多出 IPv6 行。</p><h2 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to &quot;备份&quot;">​</a></h2><p>在 <strong>网站配置 → 数据备份与恢复</strong> 里勾选 <strong>内核与入站</strong>，会导出节点上的内核、所有入站（包括导入的节点）、中转线路和流量统计基准。所有订阅（包括分享出去的）也包含在内。恢复后面板会把内核配置重新推到在线的节点，离线的节点重连时自动补上。注意配置键的过滤口径：导出时<strong>未分类的配置键</strong>（例如经 API 写过的自定义键）按默认敏感口径被静默剔除、不进备份文件，导入方向则保留未分类键——自定义键不要指望随备份迁移（同口径见 <a href="./gist-backup">Gist 备份</a>）。</p><p>恢复时的引用处置口径：导入的附属引用（限速绑定、入站的来源 / 出站 / 分流目标等）若指向不存在的行，会被剥离而不是整行丢弃，处置结果计入导入回执的 <code>ImportWarnings</code>；日报台账键（<code>notify_daily_last</code> 等运行状态）不随备份恢复，不会把当前值回滚成备份里的旧值；备份中的内核或中转（relay）行被替换时，备份外指向旧行的引用会重指向恢复后的新行，同样计入 <code>ImportWarnings</code>，不会静默悬空。</p><p>本地导入的取消口径：提交导入后，面板先生成一份导入前自动备份快照；快照完成、开始写入之前关闭页面或断开网络，导入整单取消、不产生任何改动；一旦开始写入，导入会在服务端整单跑完，关闭页面或断网不影响导入完成、也无法再取消，请等待导入完成后再核对结果。同一时刻只允许一单备份导入，导入进行中再次提交会被拒绝并提示。</p><p>注意：备份同样包含节点 SSH 配置与联邦（面板共享）的共享定义，敏感程度与面板数据库相当，备份文件请按凭据文件同等保管、不要随意外发。3.0.9 之前导出的备份不包含这部分，升级后请重新导出一次。（注：3.0.x 是本项目上游的旧版本线；现行版本导出的备份均包含这部分，这句只针对从旧版本线带过来的存量备份。）</p><p>1.4.6 起可把同一份全量备份加密后上传到个人 GitHub 账号的私密 Gist、并定时自动上传（默认关闭、加密必填、最近 10 个版本可恢复）：见 <a href="./gist-backup">Gist 备份</a>。</p><p>下一步：<a href="./relay">对接中转</a></p><h2 id="pending-delete-管理接口-管理员" tabindex="-1">Pending Delete 管理接口（管理员） <a class="header-anchor" href="#pending-delete-管理接口-管理员" aria-label="Permalink to &quot;Pending Delete 管理接口（管理员）&quot;">​</a></h2><p>当节点离线时删除转发，系统会将其标记为 pending-delete（status=2），由后台任务按退避策略（1m/5m/30m/2h，上限 24h）自动重试清理。以下接口用于可观测性：</p><h3 id="post-api-v1-node-nftables-pending-deletes" tabindex="-1">POST /api/v1/node/nftables/pending-deletes <a class="header-anchor" href="#post-api-v1-node-nftables-pending-deletes" aria-label="Permalink to &quot;POST /api/v1/node/nftables/pending-deletes&quot;">​</a></h3><p>列出所有待清理的转发。</p><ul><li><strong>权限</strong>：仅管理员（roleID=0）</li><li><strong>请求</strong>：POST，无参数（需 Authorization 头带 JWT）</li><li><strong>响应</strong>：<code>{code, msg, data: [{forwardId, forwardName, nodeId, nodeName, retryCount, nextRetryAt, lastError, createdAt}], ts}</code>（字段名为 camelCase）</li><li><strong>用途</strong>：退避耗尽转人工后，管理员在此查看哪些转发需要手动处理</li></ul><h3 id="相关行为" tabindex="-1">相关行为 <a class="header-anchor" href="#相关行为" aria-label="Permalink to &quot;相关行为&quot;">​</a></h3><ul><li>pending 行不会出现在转发列表中（<code>ListForwards</code> 恒过滤 status=2），只能通过上面的 pending-deletes 接口查看</li><li>配额释放、恢复、批量操作均不会复活 pending 行</li><li>隧道删除时，pending 行合并进同节点清理批次</li><li>切换节点转发模式（agent ↔ nftables）时，若该节点是已有转发隧道的入口节点会被拒绝：切换不迁移数据面服务，须先删除或移出该隧道的转发（或编辑隧道去掉本节点入口）后再切换</li></ul><h2 id="删除节点" tabindex="-1">删除节点 <a class="header-anchor" href="#删除节点" aria-label="Permalink to &quot;删除节点&quot;">​</a></h2><p>删除确认窗里有一个默认勾选的 <strong>同时卸载服务器上的 agent</strong>。勾不勾选，删掉的范围不同，先分清。</p><p><strong>与升级类操作的在途互斥（先看这一条）</strong>：删除与节点升级、回退、卸载共用同一份在途登记，同一节点同一时刻只允许一个这类操作在途。节点有升级 / 回退正在进行时发起删除，会被<strong>整体拒绝</strong>、回执点名在途的操作（形如「该节点已有升级操作正在进行，请等待其完成后再试」）——这是预期互斥、不是故障，等在途操作完成后再删即可，不要反复重试。反过来，删除（尤其连带卸载）进行期间，该节点的升级、回退也会按同一口径被拒并点名。批量删除时逐节点判定：被拒的节点在批量回执里逐条点名，其余节点照常删除。</p><p><strong>面板侧清理（不论勾选与否）</strong>：面板会先尝试通知节点清理它上面的转发服务和 nft 规则，然后再删除面板里的节点记录。但这个清理是<strong>尽力而为、不保证成功</strong>：</p><ul><li>节点在删除时离线或不可达，清理指令发不到节点，删除仍会继续（否则离线节点永远删不掉）</li><li>清理失败只会记进面板日志，不会阻止删除</li><li>删除节点时，如果其他节点上的入站正把本节点入站选作默认去向或分流去向，确认弹窗与删除响应会点名这些将被打断的跨节点引用（回传清单）；请先解除引用，或确认接受这些入站的出站流量被丢弃后再删除</li></ul><p><strong>勾选「同时卸载 agent」（默认）</strong>：面板会让节点上的 agent 自卸载——停掉内核进程、删除自建的 nft 表、恢复调优改过的系统参数，并删除安装目录（脚本形态）或清空数据目录（容器形态，容器本体会留一个卸载标记空转，请之后手动删掉容器）。删除回执会点名卸载结果是哪一种：</p><ul><li><strong>正在卸载</strong>：节点在线且 agent 已确认，面板提示 agent 正在卸载</li><li><strong>下次连接时自动卸载</strong>：节点离线或未确认时先登记（面板提示「已登记：它下次连接面板时将自动卸载 agent」），节点下次连接面板时会被拦截并自动执行卸载，不必再回面板操作。登记保留期为 <strong>180 天</strong>：超期未连接的登记会在下一次新登记写入时被顺带清理（没有新登记写入时，旧登记实际仍在）；超过 180 天才回连的节点若登记已被清掉，不会再被自动卸载，届时按「版本过旧、需手动卸载」同样的方式登录节点机手动清理</li><li><strong>版本过旧、需手动卸载</strong>：节点上的 agent 版本过旧、没有自卸载能力，回执会点名提示，需要登录节点机手动清理</li></ul><blockquote><p>只想把这台服务器<strong>移到另一个面板</strong>管理时，请<strong>取消勾选</strong>：否则 agent 自卸载会把自己删掉，迁过去还得重装。</p></blockquote><p><strong>不勾选时</strong>：只删面板记录和上面的转发清理，agent 本体、内核进程与配置文件都留在节点机上继续运行，之后想清理要自己登录节点机处理。</p><p><strong>在节点机上用安装脚本卸载（脚本形态）</strong>：登录节点机重新下载安装脚本、选「3. 卸载」，清理范围与面板自卸载一致：停掉并禁用 agent 服务；赶在删安装目录之前按调优备份恢复调优前的系统参数（sysctl 原值写回、整形前队列回放）；删除调优留在宿主机上的文件（<code>/etc/sysctl.d/99-flmx-tuning.conf</code>、<code>/etc/modules-load.d/flmx-bbr.conf</code>、队列整形服务 <code>flmx-tuning-qdisc.service</code>）；删除 agent 自建的 nft 表（<code>flmx_kernel</code>、<code>flvx_kernel</code>、<code>flmx_hop_probe</code>）；最后删除服务文件与安装目录。<strong>共存例外</strong>：其中两项与旧谱系 agent 同名共用——改名前 legacy 名的调优文件 <code>/etc/sysctl.d/99-flvx-tuning.conf</code> 与 nft 表 <code>flvx_kernel</code>；若卸载时仍检测到旧式 gost agent 足迹，这两项会被<strong>跳过不删</strong>、在卸载输出中逐项点名并给出人工删除法（归属不明时不误删他方资源），其余清理照常执行；无旧式足迹时两项照常删除。卸载输出会逐项列明每一项的清理结果，未能完成的项会单独标出并给出人工清理法。两条路径的差别只在触发方式与对象：脚本卸载不会删面板里的节点记录（删完后请再回面板删除该节点，或先在面板删节点时取消勾选、再到节点机跑脚本卸载），且只适用于脚本形态节点。例外：若整形前的队列备份已丢失，两条路径都会标明队列整形无法恢复、其余清理照常执行——sysctl 原值仍按调优备份写回、宿主调优文件照常删除；面板自卸载时这一情况会在删除回执里点名（不再是无说明的「正在卸载」），残留的运行时整形在宿主机重启后随 tc 状态自动消散。</p><p>所以：<strong>删除节点成功，不等于节点机上的运行时已经清干净</strong>（不勾选、或勾选但回执点名版本过旧时尤其如此）。推荐顺序：</p><ol><li>优先在节点还在线时删除，并保持默认勾选，让自卸载当场执行、回执为「正在卸载」</li><li>离线删除且保持勾选的，等节点下次上线即自动卸载，无需再管</li><li>只有不勾选、或回执点名 agent 版本过旧时，才需要登录节点机手动清理：重新下载安装脚本选「3. 卸载」，按上面脚本卸载的范围清干净——不要只停服务、只删安装目录，调优宿主文件与 nft 表残留在宿主机上会开机重放、长期存续</li></ol><h2 id="出站-ip-策略" tabindex="-1">出站 IP 策略 <a class="header-anchor" href="#出站-ip-策略" aria-label="Permalink to &quot;出站 IP 策略&quot;">​</a></h2><p>新建 / 编辑入站的<strong>高级选项</strong>，或入站的<strong>出站</strong>里，可设置“出站 IP 策略”：</p><ul><li><strong>自动（IPv4 / IPv6）</strong>：沿用内核和系统的默认选择。</li><li><strong>仅 IPv4 出站</strong>：保持入站监听地址不变，域名只解析 IPv4；直接请求 IPv6 目标会被拒绝，不会回退到 IPv6。这样客户端仍可通过 IPv6 连到节点，而本机的业务出站只走 IPv4。</li><li><strong>仅 IPv6 出站</strong>：保持入站监听地址不变，域名只解析 IPv6；直接请求 IPv4 目标会被拒绝，不会回退到 IPv4。节点必须具备可用的 IPv6 地址和路由，只支持 IPv4 的网站无法访问。</li><li><strong>优先 IPv4（失败回退 IPv6）</strong>：保留双栈解析，TCP 先尝试 IPv4；连接失败或约 250ms 内尚未连通时启动 IPv6 备用尝试，采用先成功的连接。域名没有 A 记录时直接尝试 IPv6。</li><li><strong>优先 IPv6（失败回退 IPv4）</strong>：与上面相反，TCP 先尝试 IPv6，失败或迟迟未连通时尝试 IPv4；域名没有 AAAA 记录时直接尝试 IPv4。</li></ul><p>优先模式需要 Xray 25.6.8+ 或 sing-box 1.12+；仅 IPv4 / 仅 IPv6 在 sing-box 上同样需要 1.12+。UDP 按解析结果优先选择地址；因为 UDP 没有连接握手，远端静默不回包无法可靠判定故障，不会自动把同一数据包重放到另一种 IP。</p><p>支持 Xray、sing-box 1.12 及以上（含 sing-box 内置 Snell），独立 Snell 内核不支持。策略按入站保存，编辑、重新下发和重启后仍生效；把节点内核降级到不支持已保存策略的版本会被拒绝。</p><p>指定出站 IP 策略时，高级 JSON 不能覆盖 <code>tag</code> 或 <code>detour</code>，以免绕过按入站生效的策略；存在冲突会提示并拒绝保存。</p><p>直连分流和用户流量统计同样遵循策略。链式 / 代理分流连接下一跳时也遵循所选 IP 策略：下一跳是与策略冲突的字面 IP 时保存会被拒绝（域名放行，由内核按同一策略解析）。网站最终看到的出口由下一跳节点决定，需要在最终落地上同样设置策略。</p>',117)])])}const b=o(a,[["render",s]]);export{p as __pageData,b as default};
